//---------------------------------------------------------------------------//
// Unit tests for tools/lina/box3
// Initial implementation generated by GitHub CoPilot (GPT-4.1)
//---------------------------------------------------------------------------//
#include "tools/lina/box3"

#include "tools/lina/vec"
#include <gtest/gtest.h>

namespace tools
{
//---------------------------------------------------------------------------//
TEST(Box3, DefaultConstruction)
{
  box3f b;
  EXPECT_TRUE(b.is_empty());
}

TEST(Box3, SetBoundsVec)
{
  vec3f min(1.0f, 2.0f, 3.0f);
  vec3f max(4.0f, 5.0f, 6.0f);
  box3f b;
  EXPECT_TRUE(b.set_bounds(min, max));
  EXPECT_FALSE(b.is_empty());
  EXPECT_FLOAT_EQ(b.min().x(), 1.0f);
  EXPECT_FLOAT_EQ(b.min().y(), 2.0f);
  EXPECT_FLOAT_EQ(b.min().z(), 3.0f);
  EXPECT_FLOAT_EQ(b.max().x(), 4.0f);
  EXPECT_FLOAT_EQ(b.max().y(), 5.0f);
  EXPECT_FLOAT_EQ(b.max().z(), 6.0f);
}

TEST(Box3, SetBoundsComponents)
{
  box3f b;
  EXPECT_TRUE(b.set_bounds({1.0f, 2.0f, 3.0f}, {4.0f, 5.0f, 6.0f}));
  EXPECT_FALSE(b.is_empty());
  EXPECT_FLOAT_EQ(b.min().x(), 1.0f);
  EXPECT_FLOAT_EQ(b.max().z(), 6.0f);
}

TEST(Box3, InvalidBounds)
{
  box3f b;
  EXPECT_FALSE(b.set_bounds({4.0f, 5.0f, 6.0f}, {1.0f, 2.0f, 3.0f}));
  EXPECT_TRUE(b.is_empty());
}

TEST(Box3, GetSize)
{
  box3f b;
  b.set_bounds(vec3f(1.0f, 2.0f, 3.0f), vec3f(4.0f, 6.0f, 8.0f));
  float dx, dy, dz;
  b.get_size(dx, dy, dz);
  EXPECT_FLOAT_EQ(dx, 3.0f);
  EXPECT_FLOAT_EQ(dy, 4.0f);
  EXPECT_FLOAT_EQ(dz, 5.0f);
}

TEST(Box3, ExtendByPoint)
{
  box3f b;
  b.set_bounds(vec3f(1.0f, 2.0f, 3.0f), vec3f(4.0f, 5.0f, 6.0f));
  b.extend_by(vec3f(0.0f, 10.0f, -1.0f));
  EXPECT_FLOAT_EQ(b.min().x(), 0.0f);
  EXPECT_FLOAT_EQ(b.min().y(), 2.0f);  // y stays the same, since 2.0f < 10.0f
  EXPECT_FLOAT_EQ(b.min().z(), -1.0f);
  EXPECT_FLOAT_EQ(b.max().x(), 4.0f);
  EXPECT_FLOAT_EQ(b.max().y(), 10.0f);
  EXPECT_FLOAT_EQ(b.max().z(), 6.0f);
}

TEST(Box3, ExtendEmptyBoxByPoint)
{
  box3f b;
  b.extend_by(vec3f(1.0f, 2.0f, 3.0f));
  EXPECT_FALSE(b.is_empty());  // Should now be non-empty
  EXPECT_FLOAT_EQ(b.min().x(), 1.0f);
  EXPECT_FLOAT_EQ(b.min().y(), 2.0f);
  EXPECT_FLOAT_EQ(b.min().z(), 3.0f);
  EXPECT_FLOAT_EQ(b.max().x(), 1.0f);
  EXPECT_FLOAT_EQ(b.max().y(), 2.0f);
  EXPECT_FLOAT_EQ(b.max().z(), 3.0f);
}

//---------------------------------------------------------------------------//
}  // namespace tools
